"""Object-oriented code: statements that read or write a field of `self` / `this`.

The component is near zero in prose and in most tokens. Inside class code it turns on when
the current statement touches an object's own field: on the `self` / `this` (or `._`, `->`)
token itself, strongly, and more weakly on the other tokens of that line. It is also weakly
positive on the `{` that opens a method body and on method-declaration keywords, and weakly
negative on statement ends. Everything else predicts 0.
"""

import re

READS = ()

FIELD_LINE = re.compile(r"\b(self|this)\.|\$this->|\bthis->")  # a line with self.x / this.x
SIGNATURE_END = re.compile(r"\)\s*(:[^{]*)?\{\s*$")  # a line ending in a function signature's '{'
CONTROL = re.compile(r"\b(if|for|while|switch|catch|else|try|with|namespace|class)\b")
DECLARATIONS = {"public", "private", "protected", "static", "void", "function", "def", "fn", "func"}
SELF_WORDS = {"self", "this", "._", "->", "(self"}
STATEMENT_ENDS = {";", ");", "();", ")", ");\n", ";\n"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    line = prefix.text_prefixes[-1][-300:].split("\n")[-1]
    in_field_line = bool(FIELD_LINE.search(line))
    if word in SELF_WORDS:
        return None, (5.0 if in_field_line else 1.0)
    if in_field_line:
        return None, 1.5
    if token.rstrip().endswith("{") and SIGNATURE_END.search(line) and not CONTROL.search(line):
        return None, 2.0
    if word in DECLARATIONS:
        return None, 1.0
    if word in STATEMENT_ENDS:
        return None, -0.5
    return None, 0.0

"""Layer 15, MLP hidden unit 2000. The component is this unit's output
(about 1.2 times its value), so the program predicts that value.

The unit is mostly a dense, context-driven signal that no short rule captures.
This program predicts only its readable spikes and is 0 elsewhere:

- Positive, on a wh-word ("what", "how", "why", ...) that opens an embedded
  clause of unknown content just after a verb of not knowing or seeing:
  "I don't know what", "can't wait to see what", "who knows what". "what"
  gets the larger value.
- Negative, on code. On an import or #include line the unit dips on a
  dotted class name ("import java.util.List;"), on the header part of
  "#include <stdio.h>", on the line's ";" and on "from". It also dips on
  "==" and "!=" comparisons.
"""

READS = ()

UNKNOWING = {"know", "knows", "knew", "see", "seeing", "wonder", "wondering",
             "idea", "telling", "sure", "curious", "guess", "clue"}
WH_WORDS = {"how", "why", "where", "who", "when"}
EQUALITY = {"==", "!="}
IMPORT_LINE = {"import", "#include"}
HEADER_PARTS = {".h", "stdio", "iostream"}


def _word(s):
    return s.strip()


def _is_class_name(w):
    # a dotted, capitalised name such as ".List"
    return len(w) > 1 and w[0] == "." and w[1].isupper()


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    docs = prefix.document_ids
    cur = _word(strs[-1])
    # the previous tokens of the same document, nearest first
    prev = []
    for i in range(len(strs) - 2, max(-1, len(strs) - 12), -1):
        if docs[i] != docs[-1]:
            break
        prev.append(_word(strs[i]))
    # the tokens on the current line before this one
    line = []
    for w in prev:
        if "\n" in w:
            break
        line.append(w)
    unknowing = any(w in UNKNOWING for w in prev[:3])
    if cur == "what" and unknowing:
        return carry, 4.3
    if cur in WH_WORDS and unknowing:
        return carry, 2.2
    if cur == "what":
        return carry, 0.7
    if cur in EQUALITY:
        return carry, -0.6
    if any(w in IMPORT_LINE for w in line):
        if _is_class_name(cur):
            return carry, -3.0
        if cur == ";":
            return carry, -1.2
        if cur == "from":
            return carry, -0.9
        if cur in HEADER_PARTS:
            return carry, -1.8
    return carry, 0.0

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:2013: a token-class mean.

The component's activation is diffuse: mean ~0, standard deviation 0.34, and it
depends on context rather than on any one token. Its best simple predictor is
the average activation of the current token's class (word, punctuation, digits,
CJK...), which explains only about 0.3% of the variance on held-out training
rows. Each class mean below was measured on training rows.
"""
import re

READS = ()

# Mean activation of each token class (measured on training rows).
CLASS_MEAN = {
    "cjk": 0.0156, "digits": -0.0206, "newline": -0.0071, "nonascii": 0.0181,
    "nosp_alpha": 0.0107, "nosp_mixed": -0.0357, "nosp_punct": -0.0370,
    "sp_alpha": 0.0172, "sp_mixed": 0.0245, "sp_punct": -0.0098, "space": -0.0040,
}


def token_class(s):
    """Coarse class of a token's text: leading space, word, punctuation, digits, script."""
    if "\n" in s:
        return "newline"
    if s.strip() == "":
        return "space"
    lead = "sp" if s[0] == " " else "nosp"
    c = s.strip()
    if re.fullmatch(r"\d+", c):
        return "digits"
    if re.fullmatch(r"[A-Za-z]+", c):
        return lead + "_alpha"
    if re.fullmatch(r"[^\w\s]+", c):
        return lead + "_punct"
    if re.search(r"[一-鿿]", c):
        return "cjk"
    if re.search(r"[^\x00-\x7f]", c):
        return "nonascii"
    return lead + "_mixed"


def step(carry, prefix, upstream):
    return carry, CLASS_MEAN.get(token_class(prefix.token_strings[-1]), 0.0)

"""Numbers in running prose.

This component fires on quantities: digits and number words ("two", "a few", "several",
"more") in English or scientific prose, most strongly when an approximating word
("about", "around", "approximately", "within", "for", "than", "over") comes just before
the number, as in "about two months" or "a few minutes". It is weaker after a currency
sign, and it goes slightly negative for numbers stuck to code symbols (underscores,
backslashes, asterisks, quotes), for bare spaces and for punctuation. Everything else is
near zero.

The program reads only the current token and the nearest earlier word of the same
document, so it is causal. Its values are rough per-class means of the component's
activation, fitted on training text; they explain only about 2% of its variance, because
most of the variation sits on ordinary words in contexts a short rule cannot see.
"""
import re

READS = ()

NUMBER_WORDS = {
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "twelve", "twenty", "thirty", "fifty", "hundred", "thousand", "million",
    "few", "several", "couple", "dozen", "half", "many", "more",
}
APPROXIMATORS = {
    "about", "around", "approximately", "roughly", "nearly", "almost", "within",
    "over", "than", "for", "least", "only", "every", "last", "next", "another", "just",
}
UNITS = {
    "minutes", "hours", "days", "weeks", "months", "years", "seconds", "miles",
    "percent", "%", "times", "feet", "inches", "km", "mm", "kg", "mg",
}
CURRENCY = {"$", "£", "€"}
CODE_SYMBOLS = set("_\\*\"`{}[]")


def previous_word(prefix):
    """The nearest earlier token of this document that is not a bare space, or ''."""
    doc = prefix.document_ids[-1]
    i = len(prefix.token_strings) - 2
    while i >= 0 and prefix.document_ids[i] == doc and prefix.token_strings[i].strip() == "":
        i -= 1
    if i < 0 or prefix.document_ids[i] != doc:
        return ""
    return prefix.token_strings[i].strip()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if re.fullmatch(r"\d", tok) or tok.lower() in NUMBER_WORDS:
        prev = previous_word(prefix)
        if prev.lower() in APPROXIMATORS:
            value = 3.0
        elif prev in CURRENCY:
            value = 1.6
        elif re.fullmatch(r"[A-Za-z]+", prev):
            value = 0.8
        elif prev and set(prev) <= CODE_SYMBOLS:
            value = -0.6
        else:
            value = 0.15
    elif tok.lower() in UNITS:
        value = 0.4
    elif tok == "":
        value = -0.2
    elif re.fullmatch(r"[^\w\s]+", tok):
        value = -0.12
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 2023: negative on words and numbers met for the first time.

Plain-terms summary. This piece reads the layer-15 MLP's hidden state and writes along one
residual direction. Its activation is mostly negative, and its large negative values sit on
tokens that introduce something new to the document: a name, a number or a word-piece that has
not appeared earlier in it. Repeats of the same thing are about zero.

  - a capitalised word in the middle of a sentence (a person, place or organisation), new in
    the document: strongly negative, most of all right after a lower-case word ("by Hazel");
    repeated: about zero;
  - a capitalised word opening a sentence, new: weakly negative;
  - an all-caps word or initialism, new: negative;
  - a digit 1-9, new: negative; repeated: mildly negative; the digit 0: about zero;
  - a lower-case piece of a word with no leading space (a word split across tokens), new:
    mildly negative;
  - everything else (ordinary words with a leading space, punctuation, spacing): about zero.

The values are the mean activation of each class on sampled training text (fitted, not
hand-tuned). Fitted on half the sample and scored on the other half, these classes explain
about 5% of the variance. This is a conceptual summary, not a model of the component: the
largest spikes (|activation| above 5, most of the variance) depend on context these rules
do not see. So the program gets the sign and rough size of the typical value, not the spikes.

The carry is the set of pieces seen so far in the current document, plus the previous token.
It resets where the document changes, as the model's attention does.
"""

READS = ()

# Mean activation per class, measured on sampled training text.
MID_CAP_NEW_AFTER_LOWER = -1.88
MID_CAP_NEW = -1.16
MID_CAP_KNOWN = 0.03
SENTENCE_CAP_NEW = -0.38
SENTENCE_CAP_KNOWN = 0.08
ALL_CAPS_NEW = -0.82
DIGIT_NEW = -0.98
DIGIT_KNOWN = -0.40
DIGIT_ZERO = 0.13
WORD_PIECE_NEW = -0.50
OTHER = -0.02

SENTENCE_END = (".", "!", "?", ":", '"', "\n")


def _opens_sentence(prev):
    """True if the previous token closes a sentence or line, so this word starts one."""
    return prev == "" or prev.rstrip(" ").endswith(SENTENCE_END)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "seen": set(), "prev": "\n"}
    cur = prefix.token_strings[-1]
    key = cur.strip()
    new = key not in carry["seen"]
    prev = carry["prev"]
    if cur[:1] == " " and cur[1:2].isupper():
        if _opens_sentence(prev):
            value = SENTENCE_CAP_NEW if new else SENTENCE_CAP_KNOWN
        elif not new:
            value = MID_CAP_KNOWN
        elif prev.strip().islower():
            value = MID_CAP_NEW_AFTER_LOWER
        else:
            value = MID_CAP_NEW
    elif key.isdigit():
        if key == "0":
            value = DIGIT_ZERO
        else:
            value = DIGIT_NEW if new else DIGIT_KNOWN
    elif key.isupper() and len(key) > 1 and cur[:1] != " ":
        value = ALL_CAPS_NEW if new else 0.0
    elif key.islower() and cur[:1] != " ":
        value = WORD_PIECE_NEW if new else 0.0
    else:
        value = OTHER
    carry["seen"].add(key)
    carry["prev"] = cur
    return carry, float(value)

"""Component layers.15.mlp.down_proj:2038: a 'list-joiner' detector.

It fires on the words and marks that join items of a series or a pair: "and", "or",
"und", "et", "и", "или", "&", "+", "vs", "whereas", "while", ...; on the separators that
end an item: ",", ";", "、", "，", "),", "],", line breaks, bullets; and it is negative on
words that announce a pair ("both", "either", "whether").

It is strongest after a noun-like item (a name, a noun, a closing bracket, a digit or a
symbol) and weak after an adjective, adverb or verb ("soft and", "clear and"), because a
conjunction that joins two adjectives or clauses is not joining parallel nouns.

The values are rough averages measured on training text, scaled to 3/4. Everything else
predicts 0. Only the previous token and the current token are read.
"""

READS = ()

import wordnet

JOINERS = {" and", " or", " und", " et", " y", " и", " или", " oder", " og", " oraz", " а",
           " &", " &&", " +", " vs", " versus", " whereas", " while", " well", "和", "以及", "及",
           "と", "와", " serta"}
SEPARATORS = {",", ";", "、", "，", "；", "),", "],", "},", ");", ",\n", ",\n\n", ")\n", "/\n", "•"}
LINE_STARTS = {"\n", "-"}
PAIR_WORDS = {" both", " either", " whether", " neither", " maybe", " perhaps"}


def is_plain_modifier(prev):
    """True if the previous token is a word WordNet knows only as adjective, adverb or verb."""
    word = prev.strip().lower()
    if not word.isalpha():
        return False
    pos = wordnet.parts_of_speech(word)
    return bool(pos) and "noun" not in pos


def ends_noun_like(prev):
    """True if the previous token ends in a digit or symbol (a closing bracket, quote or maths sign)."""
    text = prev.strip()
    return bool(text) and (text[-1].isdigit() or not text[-1].isalnum())


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    modifier = is_plain_modifier(prev)
    if cur in JOINERS:
        if modifier:
            return carry, 0.3
        return carry, 3.0 if ends_noun_like(prev) else 1.6
    if cur in SEPARATORS:
        return carry, 0.15 if modifier else 0.75
    if cur in LINE_STARTS:
        return carry, 0.5
    if cur in PAIR_WORDS:
        return carry, -0.4
    return carry, 0.0

"""Layer 15, MLP hidden unit 2043 (the component is almost entirely this unit: about two
thirds of its read direction's squared norm sits on that one hidden unit).

This unit is almost silent: its typical magnitude is under 1, and it has rare, large
spikes, most of them negative, which need its gate to be open (positive). Its spikes are
context-dependent (the same word can be strongly negative in one place and positive in
another), so no word list captures most of its variance. This program captures the part a
word can explain: it predicts a fixed value for a few concept groups of tokens, and 0 for
everything else. It explains only about 1% of the variance.

  - web-post metadata and forum boilerplate ("Posted", "Views", "Joined", "wrote"): strongly
    negative
  - task-progress verbs in tool output ("completed", "finished", "passed"): negative
  - size and unit tokens ("KB", "ms"): negative
  - file-path, URL and code-identifier pieces ("://", "/local", "usr", "github"): mildly positive

Values are the groups' mean activations on training text. Each step reads only the newest token.
"""

READS = ()

POST_META = {
    "Posted", " Posted", "posted", " posted", "Posts", " Posts",
    "Views", " Views", "views", " views", "Joined", " Joined",
    "Tags", " Tags", "Published", "Filed", "Ratings", " Ratings",
    " wrote", " edited", " reserved", "permalink", " replies", " comments",
}
PROGRESS = {" completed", " finished", " passed", " PASS", " successfully", " exit"}
UNITS = {" KB", " kB", "KB", "kB", " ms", " Ki"}
CODE_PATH = {
    "://", "/local", "/bin", "/app", "usr", "\tmod", "index",
    "github", "node", "conda", "cgi", "Users", "internal",
}

GROUP_VALUE = {}
for tokens, value in [(POST_META, -3.5), (PROGRESS, -2.6), (UNITS, -2.8), (CODE_PATH, 0.9)]:
    for tok in tokens:
        GROUP_VALUE[tok] = value


def step(carry, prefix, upstream):
    return carry, GROUP_VALUE.get(prefix.token_strings[-1], 0.0)
